\[]*
+)+?[[:space:]]*${SSSD_OPT}"
if grep -qzosP $PAM_OPT_REGEX $SSSD_CONF; then sed -i "s/${SSSD_OPT}[^(
)]*/${SSSD_OPT} = ${SSSD_OPT_VAL}/" $SSSD_CONF elif grep -qs $PAM_REGEX $SSSD_CONF; then sed -i "/$PAM_REGEX/a ${SSSD_OPT} = ${SSSD_OPT_VAL}" $SSSD_CONF else mkdir -p /etc/sssd touch $SSSD_CONF echo -e "[pam]
${SSSD_OPT} = ${SSSD_OPT_VAL}" >> $SSSD_CONF fi

SSSD_SERVICES_PAM_REGEX="^[[:space:]]*\[sssd]([^
]*
+)+?[[:space:]]*services.*pam.*$" SSSD_SERVICES_REGEX="^[[:space:]]*\[sssd]([^
]*
+)+?[[:space:]]*services.*$" SSSD_PAM_SERVICES="[sssd] services = pam" SSSD_CONF="/etc/sssd/sssd.conf"
# If there is services line with pam, good # If there is services line without pam, append pam # If not echo services line with pam grep -q "$SSSD_SERVICES_PAM_REGEX" $SSSD_CONF || \ grep -q "$SSSD_SERVICES_REGEX" $SSSD_CONF && \ sed -i "s/$SSSD_SERVICES_REGEX/&, pam/" $SSSD_CONF || \ echo "$SSSD_PAM_SERVICES" >> $SSSD_CONF

